const KEY='alasg-imperio-v01';const money=n=>Number(n).toLocaleString('pt-BR',{style:'currency',currency:'BRL',maximumFractionDigits:0});const num=n=>Math.round(n).toLocaleString('pt-BR');const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function initial(){return {day:0,cash:20324200,initialCash:20324200,rev:0,expenses:0,trips:[],completed:0,fleet:structuredClone(INITIAL),ledger:[],sequence:0,expansion:false,notice:'Quilometragens iniciais estimadas na simulação; não são leituras reais.',minute:0,auto:true,paused:false,speed:12,lastTick:Date.now(),autoJobs:0}}
let s;try{s=JSON.parse(localStorage.getItem(KEY))||initial();if(!s.fleet||s.fleet.length!==200)throw 1}catch(e){s=initial()}
s.minute??=0;s.auto??=true;s.paused??=false;s.speed??=12;s.lastTick??=Date.now();s.tickRemainder??=0;s.autoJobs??=0;s.deals??=[];s.chat??=[];s.retired??=[];s.nextAsset??=113;s.lastOfferDay??=-1;s.minute=Number(s.minute)||0;s.trips.forEach(t=>{t.driven=Number(t.driven)||0;t.totalDays=Number(t.totalDays)||Number(t.days)||1});let tab='diretoria',fleetFilter='cavalo',search='',selected=null;let staffDraft='',staffSelected='Ricardo';const tractors=()=>s.fleet.filter(v=>v.kind==='cavalo'),trailers=()=>s.fleet.filter(v=>v.kind==='carreta');const free=v=>!s.trips.some(t=>t.tractor===v.id&&t.days>0);function save(){try{localStorage.setItem(KEY,JSON.stringify(s))}catch(e){toast('Não foi possível salvar. Exporte seu progresso.')}}function toast(t){const x=document.getElementById('toast');x.textContent=t;x.style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>x.style.display='none',3300)}
const jobs=[{from:'Juiz de Fora',to:'Belo Horizonte',km:270,days:1,price:5800},{from:'Juiz de Fora',to:'Rio de Janeiro',km:190,days:1,price:4900},{from:'Juiz de Fora',to:'São Paulo',km:480,days:2,price:9700},{from:'Juiz de Fora',to:'Campinas',km:540,days:2,price:11000},{from:'Juiz de Fora',to:'Vitória',km:430,days:2,price:9300},{from:'Juiz de Fora',to:'Curitiba',km:880,days:3,price:18100}];
function dateStr(){let d=new Date(Date.UTC(2029,10,30+s.day));return d.toLocaleDateString('pt-BR',{timeZone:'UTC',day:'2-digit',month:'2-digit',year:'numeric'})}
function addLedger(type,description,value){s.ledger.unshift({day:s.day,type,description,value});s.ledger=s.ledger.slice(0,350)}
function shownKm(v){let t=s.trips.find(t=>v.kind==='cavalo'?t.tractor===v.id:t.trailer===v.id);return Math.round(v.km+(t?Math.min(t.km-t.driven,(t.km/Math.max(1,t.totalDays))*s.minute/1440):0))}
function status(v){let lim=v.kind==='cavalo'?500000:1000000,attention=v.kind==='cavalo'?450000:900000;return shownKm(v)>=lim?'LIMITE':shownKm(v)>=attention?'ATENÇÃO':'NORMAL'}
function renderHeader(){document.getElementById('clock').innerHTML=dateStr()+' '+String(Math.floor(s.minute/60)).padStart(2,'0')+':'+String(s.minute%60).padStart(2,'0')+'<br>SIMULAÇÃO • TEMPO CONTÍNUO';document.getElementById('cash').textContent=money(s.cash);document.getElementById('fleetCount').textContent=tractors().length+' / '+trailers().length;document.getElementById('profit').textContent=money(s.rev-s.expenses);document.getElementById('activeTrips').textContent=s.trips.length;let sm=document.getElementById('sceneMoney');if(sm)sm.textContent='Caixa atual: '+money(s.cash)}
function render(){if(tab==='diretoria2'){const inp=document.getElementById('staffMessage'),sel=document.getElementById('staffPerson');if(inp)staffDraft=inp.value;if(sel)staffSelected=sel.value;}renderHeader();document.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));let c=document.getElementById('content');c.innerHTML=({diretoria:renderDashboard,frota:renderFleet,fretes:renderJobs,financas:renderFinance,gestao:renderManage,diretoria2:renderBoard}[tab])();if(tab==='diretoria2'){let sel=document.getElementById('staffPerson'),inp=document.getElementById('staffMessage');if(sel)sel.value=staffSelected;if(inp)inp.value=staffDraft;}draw()}
function renderDashboard(){let alerts=s.fleet.filter(v=>status(v)!=='NORMAL');return `<div class="panel"><div class="flex"><h3>Bom dia, diretor</h3><span class="badge">Ricardo • Gestão de frota</span></div><p class="muted">A ALASG está em operação. Ricardo procura manter todos os conjuntos disponíveis em viagens, conforme fretes, caixa e limites de segurança. Ricardo e a equipe despacham fretes automaticamente; você administra as decisões estratégicas.</p><div class="actions"><button class="btn" onclick="setTab('fretes')">Ver viagens automáticas</button><button class="btn secondary" onclick="setTab('frota')">Ver frota</button><button class="btn secondary" onclick="setTab('financas')">Financeiro</button><button class="btn" onclick="setTab('diretoria2')">🤝 Diretoria e negociações</button></div></div><div class="panel"><h3>📊 Situação operacional</h3><div class="row flex"><span>Conjuntos em viagem</span><b>${s.trips.length}</b></div><div class="row flex"><span>Fretes concluídos</span><b>${s.completed}</b></div><div class="row flex"><span>Veículos em atenção / limite</span><b>${alerts.length}</b></div><div class="row flex"><span>Expansão da garagem</span><span class="pill warn">Suspensa</span></div></div><div class="panel"><h3>👨‍💼 Ricardo informa</h3><p class="muted">${alerts.length?`Existem ${alerts.length} equipamentos com alerta de quilometragem. Confira a frota.`:'Nenhum equipamento atingiu a faixa de atenção de quilometragem.'}</p><p class="note">Os 200 valores iniciais vieram da planilha simulada. A rodagem futura é calculada pelas viagens realizadas neste jogo.</p></div>`}
function renderFleet(){let a=s.fleet.filter(v=>v.kind===fleetFilter&&(v.id.includes(search)||v.model.toLowerCase().includes(search.toLowerCase()))).sort((a,b)=>a.id.localeCompare(b.id));return `<div class="panel"><h3>🚛 Controle de frota</h3><div class="actions"><button class="btn" onclick="setTab('diretoria2')">Comprar caminhões / carretas</button><button class="btn secondary" onclick="setTab('diretoria2')">Negociar e vender</button></div><div class="grid2"><button class="btn ${fleetFilter==='cavalo'?'':'secondary'}" onclick="fleetFilter='cavalo';render()">${tractors().length} cavalos</button><button class="btn ${fleetFilter==='carreta'?'':'secondary'}" onclick="fleetFilter='carreta';render()">${trailers().length} carretas</button></div><input class="search" style="margin-top:10px" placeholder="Buscar patrimônio (ex.: 0101)" value="${esc(search)}" oninput="search=this.value;renderFleetList()"><div class="list" id="fleetList">${fleetRows(a)}</div></div>`}
function fleetRows(a){return a.map(v=>{let st=status(v),lim=v.kind==='cavalo'?500000:1000000;return `<div class="row" onclick="vehicle('${v.kind}','${v.id}')" style="cursor:pointer"><div class="flex"><b>#${v.id} <span class="muted mini">${esc(v.model)}</span></b><span class="pill ${st==='NORMAL'?'':st==='ATENÇÃO'?'warn':'danger'}">${st}</span></div><div class="flex mini muted" style="margin-top:6px"><span>${num(shownKm(v))} km</span><span>Faltam ${num(Math.max(0,lim-shownKm(v)))} km</span></div><div class="bar"><i style="width:${Math.min(100,100*shownKm(v)/lim)}%"></i></div></div>`}).join('')||'<p class="muted">Nenhum veículo encontrado.</p>'}
function renderFleetList(){let a=s.fleet.filter(v=>v.kind===fleetFilter&&(v.id.includes(search)||v.model.toLowerCase().includes(search.toLowerCase()))).sort((a,b)=>a.id.localeCompare(b.id));document.getElementById('fleetList').innerHTML=fleetRows(a)}
function vehicle(kind,id){let v=s.fleet.find(x=>x.kind===kind&&x.id===id);if(!v)return;let lim=kind==='cavalo'?500000:1000000,st=status(v);showModal('vehicle',v)}
function renderJobs(){let freeTractors=tractors().filter(v=>free(v)&&status(v)!=='LIMITE');return `<div class="panel"><h3>📍 Central de fretes</h3><div class="row flex"><span>Operação autônoma</span><b style="color:var(--green)">ATIVA</b></div><div class="row flex"><span>Fretes despachados pelo Ricardo</span><b>${s.autoJobs||0}</b></div><p class="muted mini">A equipe comercial e Ricardo aceitam fretes automaticamente. Você não precisa despachar caminhões. Receita entra somente na entrega; diesel, pedágio, motorista e custos operacionais são descontados.</p><div class="list">${jobs.map((j,i)=>`<div class="row"><div class="flex"><b>${j.from} → ${j.to}</b><b style="color:var(--green)">${money(j.price)}</b></div><div class="flex mini muted" style="margin:7px 0"><span>${num(j.km)} km • ${j.days} dia(s)</span><span>Margem estimada: ${money(j.price-estCost(j.km))}</span></div><span class="pill">Despacho pelo Ricardo</span></div>`).join('')}</div></div><div class="panel"><h3>🛣️ Viagens em andamento (${s.trips.length})</h3>${s.trips.length?s.trips.map(t=>`<div class="row flex"><div><b>#${t.tractor} → ${esc(t.to)}</b><div class="muted mini">${t.days} dia(s) restantes • ${num(t.km)} km totais</div></div><span class="pill">Em rota</span></div>`).join(''):'<p class="muted">A operação automática despachará caminhões conforme o relógio do jogo.</p>'}</div>`}
function estCost(km){return Math.round(km*5.8+650)}
function startJob(i,automatic=false){let j=jobs[i],v=tractors().filter(v=>free(v)&&status(v)!=='LIMITE').sort((a,b)=>a.km-b.km)[0];let used=new Set(s.trips.map(t=>t.trailer)),tr=trailers().find(t=>!used.has(t.id)&&status(t)!=='LIMITE');if(!v||!tr){toast('Não há conjunto disponível.');return}let cost=estCost(j.km);if(s.cash<cost){toast('Caixa insuficiente para cobrir o frete.');return}s.cash-=cost;s.expenses+=cost;addLedger('Despesa','Custo de frete '+j.to,-cost);s.trips.push({id:++s.sequence,tractor:v.id,trailer:tr.id,to:j.to,km:j.km,days:j.days,totalDays:j.days,price:j.price,cost,driven:0});if(!automatic){save();render();toast('Frete iniciado: cavalo #'+v.id+' e carreta #'+tr.id)}else{s.autoJobs++}}
function advance(days,silent=false){for(let d=0;d<days;d++){s.day++;autoDispatch();offerRenewals();for(let i=s.trips.length-1;i>=0;i--){let t=s.trips[i],v=tractors().find(v=>v.id===t.tractor),tr=trailers().find(v=>v.id===t.trailer);let driven=t.days===1?t.km-t.driven:Math.round((t.km-t.driven)/t.days);v.km+=driven;tr.km+=driven;t.driven+=driven;t.days--;if(t.days<=0){s.cash+=t.price;s.rev+=t.price;addLedger('Receita','Frete entregue em '+t.to,t.price);s.completed++;s.trips.splice(i,1)}}autoDispatch()}if(!silent){save();render();toast('Avançamos '+days+' dia(s). '+s.completed+' fretes concluídos no total.')}}
function autoDispatch(){if(!s.auto)return;let target=Math.max(0,Math.min(tractors().length,trailers().length));let needed=Math.max(0,target-s.trips.length);for(let i=0;i<needed;i++){let j=(s.day*13+i*7+Math.floor(i/6))%jobs.length;let available=tractors().some(v=>free(v)&&status(v)!=='LIMITE');if(!available)break;startJob(j,true)}}
function togglePause(){s.paused=!s.paused;s.lastTick=Date.now();save();render();toast(s.paused?'Operação pausada':'Operação retomada')}
function changeSpeed(n){s.speed=Number(n);save();render()}
function tick(){let now=Date.now(),elapsed=Math.max(0,Math.min(now-s.lastTick,7*86400000));s.lastTick=now;if(s.paused)return;s.tickRemainder=(s.tickRemainder||0)+elapsed*s.speed/1000;let mins=Math.floor(s.tickRemainder);s.tickRemainder-=mins;if(!mins)return;s.minute+=mins;let days=Math.floor(s.minute/1440);s.minute%=1440;if(days)advance(Math.min(days,7),true);save();if(tab==='diretoria2'){renderHeader();draw()}else render()}
function renderFinance(){return `<div class="panel"><h3>💰 Resultado desde o início desta versão</h3><div class="row flex"><span>Receitas de fretes entregues</span><b>${money(s.rev)}</b></div><div class="row flex"><span>Custos operacionais lançados</span><b>${money(s.expenses)}</b></div><div class="row flex"><span>Resultado operacional do jogo</span><b style="color:var(--green)">${money(s.rev-s.expenses)}</b></div><div class="row flex"><span>Caixa disponível</span><b>${money(s.cash)}</b></div><p class="note">O caixa atual muda com os custos pagos no despacho e os recebimentos na entrega. A cifra impressa na imagem da sede é decorativa e não representa o caixa atual. O saldo inicial de R$ 20.324.200 é referência provisória da história. Este resultado NÃO representa lucro líquido contábil completo: despesas fixas, impostos e obrigações históricas ainda serão implementados.</p></div><div class="panel"><h3>📒 Lançamentos</h3><div class="list">${s.ledger.length?s.ledger.map(l=>`<div class="row flex"><div><b>${esc(l.description)}</b><div class="muted mini">Dia ${l.day} • ${l.type}</div></div><b style="color:${l.value>=0?'#85efb1':'#ffb6a3'}">${money(l.value)}</b></div>`).join(''):'<p class="muted">Sem lançamentos nesta versão.</p>'}</div></div>`}
function renderManage(){return `<div class="panel"><h3>⏱ Operação em tempo contínuo</h3><p class="muted">O relógio anda sozinho, os fretes são despachados automaticamente e as entregas geram receitas e quilômetros. Não é necessário tocar em avançar.</p><div class="row flex"><span>Relógio</span><b>${s.paused?'PAUSADO':'RODANDO'}</b></div><div class="row flex"><span>Velocidade</span><select class="search" style="width:160px" onchange="changeSpeed(this.value)"><option value="1" ${s.speed===1?'selected':''}>1 min / segundo</option><option value="12" ${s.speed===12?'selected':''}>12 min / segundo</option><option value="60" ${s.speed===60?'selected':''}>1 hora / segundo</option></select></div><button class="btn secondary" onclick="togglePause()">${s.paused?'▶ Retomar':'⏸ Pausar'}</button><p class="note">Quando o jogo fica fechado, recupera até 7 dias simulados ao reabrir. Para continuar funcionando sem abrir o jogo, seria necessário um servidor online.</p></div><div class="panel"><h3>🏢 Regras da ALASG</h3><div class="row flex"><span>Renovação dos cavalos</span><b>500.000 km</b></div><div class="row flex"><span>Atenção dos cavalos</span><b>450.000 km</b></div><div class="row flex"><span>Renovação das carretas</span><b>1.000.000 km</b></div><div class="row flex"><span>Atenção das carretas</span><b>900.000 km</b></div><div class="row flex"><span>Novas compras</span><span class="pill warn">Exigem autorização</span></div><div class="row flex"><span>Expansão para 300 conjuntos</span><span class="pill warn">Suspensa</span></div></div><div class="panel"><h3>💾 Dados e progresso</h3><p class="muted mini">O jogo salva automaticamente neste navegador e simula até 7 dias de ausência quando reaberto. Para mudar de celular ou evitar perdas, exporte uma cópia.</p><div class="actions"><button class="btn" onclick="exportSave()">Exportar</button><button class="btn secondary" onclick="document.getElementById('importFile').click()">Importar</button><button class="btn secondary" onclick="showModal('reset')">Reiniciar</button></div><input type="file" id="importFile" accept=".json,application/json" style="display:none" onchange="importSave(event)"></div>`}
function setTab(x){tab=x;render()}
function showModal(type,v){let h='';if(type==='vehicle'){let lim=v.kind==='cavalo'?500000:1000000;h=`<h2>${v.kind==='cavalo'?'🚛 Cavalo mecânico':'🚚 Carreta'} #${v.id}</h2><p>${esc(v.model)}</p><div class="kpi">${num(shownKm(v))} km</div><div class="bar"><i style="width:${Math.min(100,100*shownKm(v)/lim)}%"></i></div><div class="row flex"><span>Situação</span><span class="pill">${status(v)}</span></div><div class="row flex"><span>Até o limite</span><b>${num(Math.max(0,lim-shownKm(v)))} km</b></div><p class="note">Quilometragem inicial simulada, acrescida dos fretes realizados no jogo.</p><button class="btn" onclick="closeModal();setTab('diretoria2');createSaleOffer('${v.kind}','${v.id}')">Solicitar avaliação de venda</button><button class="btn secondary" onclick="closeModal()">Fechar</button>`}else if(type==='menu'){h=`<h2>🎮 ALASG — Menu</h2><p class="muted">Versão 0.7 • navegação funcional e despacho revisado</p><div class="row flex"><span>Data da simulação</span><b>${dateStr()}</b></div><div class="row flex"><span>Fretes concluídos</span><b>${s.completed}</b></div><div class="grid2" style="margin-top:15px"><button class="btn" onclick="exportSave()">Exportar progresso</button><button class="btn secondary" onclick="closeModal();setTab('gestao')">Configurações</button></div><p class="note">Sede ilustrada com pátio dinâmico: somente veículos disponíveis aparecem estacionados. Não há conexão com GPS, bancos ou telemetria real.</p><button class="btn secondary" style="margin-top:10px" onclick="closeModal()">Voltar ao jogo</button>`}else if(type==='reset'){h=`<h2>Reiniciar o jogo?</h2><p>Isso apaga o progresso salvo neste navegador e restaura a frota e o caixa iniciais.</p><div class="grid2"><button class="btn secondary" onclick="closeModal()">Cancelar</button><button class="btn gold" onclick="s=initial();save();closeModal();render();toast('Jogo reiniciado')">Confirmar</button></div>`}document.getElementById('modal').innerHTML=h;document.getElementById('modalbg').style.display='flex'}function closeModal(){document.getElementById('modalbg').style.display='none'}
function exportSave(){let blob=new Blob([JSON.stringify({game:'ALASG',version:1,data:s},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='ALASG-progresso-'+dateStr().replaceAll('/','-')+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);toast('Backup exportado.')}
async function importSave(e){let f=e.target.files?.[0];if(!f)return;try{let data=JSON.parse(await f.text()),x=data.data;if(data.game!=='ALASG'||!Array.isArray(x.fleet)||x.fleet.length<1||!Number.isFinite(x.cash)||!Array.isArray(x.trips))throw Error('Arquivo inválido');s=x;save();render();toast('Progresso importado!')}catch(e){toast('Não foi possível importar: arquivo inválido.')}e.target.value=''}
// Sede ALASG: cenário vetorial desenhado no canvas, sem imagem fixa ou placas cinzas.
const yardCanvas=document.getElementById('fleetOverlay'),yardCtx=yardCanvas.getContext('2d');
let yardHits=[],yardAnim=new Map(),yardFrame=0;
function polygon(points,color,stroke='#0000'){yardCtx.beginPath();points.forEach(([x,y],i)=>i?yardCtx.lineTo(x,y):yardCtx.moveTo(x,y));yardCtx.closePath();yardCtx.fillStyle=color;yardCtx.fill();yardCtx.strokeStyle=stroke;yardCtx.lineWidth=2;yardCtx.stroke()}
function rect(x,y,w,h,color){yardCtx.fillStyle=color;yardCtx.fillRect(x,y,w,h)}
function label(t,x,y,size=19,color='#f6f8e7'){yardCtx.font=`bold ${size}px system-ui`;yardCtx.fillStyle='#081e23bb';let w=yardCtx.measureText(t).width;yardCtx.fillRect(x-7,y-size-5,w+14,size+13);yardCtx.fillStyle=color;yardCtx.fillText(t,x,y)}
function building(x,y,w,h,title,doors=0){rect(x+11,y+17,w,h,'#0006');rect(x,y,w,h,'#a6afb0');rect(x+5,y+7,w-10,h-13,'#c6d0ce');rect(x+5,y+7,w-10,8,'#e3e8df');rect(x,y+h-20,w,20,'#143f32');for(let i=0;i<doors;i++){let dw=(w-28)/doors;rect(x+12+i*dw,y+h-17,dw-8,17,'#1d2931');rect(x+15+i*dw,y+h-15,dw-14,3,'#78a6b6')}label(title,x+12,y+32,16)}
function truck(x,y,scale,id,heading=0,alpha=1){let c=yardCtx;c.save();c.translate(x,y);c.rotate(heading);c.scale(scale,scale);c.globalAlpha=alpha;c.fillStyle='#0006';c.fillRect(-13,13,83,15);c.fillStyle='#eceee7';c.fillRect(10,-12,60,23);c.fillStyle='#a9b5b4';c.fillRect(12,-9,56,4);c.strokeStyle='#778b89';c.strokeRect(10,-12,60,23);c.fillStyle='#0c684a';c.fillRect(-15,-13,27,26);c.fillStyle='#36a57b';c.fillRect(-13,-12,25,8);c.fillStyle='#9bd1df';c.fillRect(-11,-8,17,7);c.fillStyle='#1c262b';for(let xx of [-11,3,23,58]){c.fillRect(xx,-17,7,5);c.fillRect(xx,12,7,5)}c.fillStyle='#b58d34';c.font='bold 10px system-ui';c.fillText('ALASG',24,5);c.restore();yardHits.push({x,y,r:Math.max(14,45*scale),id})}
function slot(i){let row=Math.floor(i/12),col=i%12;return {x:290+col*95,y:295+row*48,scale:.70}}
function draw(){let r=yardCanvas.getBoundingClientRect();if(!r.width)return;let dpr=Math.min(devicePixelRatio||1,2),w=Math.round(r.width*dpr),h=Math.round(r.height*dpr);if(yardCanvas.width!==w||yardCanvas.height!==h){yardCanvas.width=w;yardCanvas.height=h}let c=yardCtx;c.setTransform(w/1600,0,0,h/900,0,0);c.clearRect(0,0,1600,900);yardHits=[];
// Piso e estruturas são renderizados diretamente; pátio vazio permanece vazio.
let sky=c.createLinearGradient(0,0,0,900);sky.addColorStop(0,'#386047');sky.addColorStop(1,'#24432e');rect(0,0,1600,900,sky);
for(let i=0;i<120;i++){let x=(i*257+37)%1600,y=(i*139+19)%900;c.beginPath();c.fillStyle=i%2?'#315d3d':'#47784b';c.arc(x,y,7+i%9,0,Math.PI*2);c.fill()}
rect(75,70,1450,750,'#b6c0b6');rect(89,84,1422,718,'#485151');for(let y=100;y<800;y+=80){rect(92,y,1416,1,'#59606030')}
// vias de circulação
rect(115,630,1360,90,'#323b3f');rect(745,180,120,580,'#323b3f');rect(115,215,1360,54,'#353e42');
for(let x=145;x<1450;x+=80){rect(x,673,37,3,'#e6dca3')}for(let y=282;y<625;y+=60){rect(802,y,3,25,'#e6dca3')}
// edifícios e setores no projeto original (sem ampliação)
building(110,95,420,108,'ADMINISTRAÇÃO');building(910,95,535,112,'OFICINA · 12 BOXES',12);
rect(1180,535,270,90,'#c9c3a6');rect(1195,545,240,13,'#c9a346');rect(1200,560,230,48,'#193e35');for(let i=0;i<4;i++){rect(1215+i*55,580,16,29,'#b9d3d1')}label('ABASTECIMENTO',1185,523,16);
building(111,740,390,58,'PORTARIA E APOIO');rect(750,722,130,80,'#b3c3ba');rect(770,722,90,80,'#1b4135');label('PORTÃO PRINCIPAL',665,848,18);rect(0,830,1600,70,'#252d32');for(let x=0;x<1600;x+=110)rect(x,863,55,4,'#ead8a1');
// vagas vazias com marcações claras
for(let i=0;i<100;i++){let p=slot(i);c.strokeStyle='#d2d8d080';c.lineWidth=2;c.strokeRect(p.x-20,p.y-19,84,36)}
let away=new Set(s.trips.map(t=>t.tractor));let present=tractors().filter(v=>!away.has(v.id));present.forEach((v,i)=>{let p=slot(i);truck(p.x,p.y,p.scale,v.id)});
let now=performance.now();for(let [id,a] of yardAnim){let progress=(now-a.start)/4000;if(progress>=1){yardAnim.delete(id);continue}let p=slot(a.slot),gate={x:812,y:776},t=a.type==='out'?progress:1-progress;truck(p.x+(gate.x-p.x)*t,p.y+(gate.y-p.y)*t,.78,id,Math.atan2(gate.y-p.y,gate.x-p.x),1)}
let stat=document.getElementById('yardStatus');if(stat)stat.textContent=`Pátio: ${present.length} cavalos • Estrada: ${away.size} • Toque em um caminhão para consultar`;
}
let previousAway=new Set(s.trips.map(t=>t.tractor));
function syncYard(){let current=new Set(s.trips.map(t=>t.tractor));for(let id of current)if(!previousAway.has(id))yardAnim.set(id,{type:'out',start:performance.now(),slot:Math.max(0,tractors().findIndex(v=>v.id===id))});for(let id of previousAway)if(!current.has(id))yardAnim.set(id,{type:'in',start:performance.now(),slot:Math.max(0,tractors().findIndex(v=>v.id===id))});previousAway=current;draw()}
yardCanvas.addEventListener('click',e=>{let r=yardCanvas.getBoundingClientRect(),x=(e.clientX-r.left)*1600/r.width,y=(e.clientY-r.top)*900/r.height;let hit=[...yardHits].reverse().find(h=>Math.hypot(h.x-x,h.y-y)<h.r);if(hit)vehicle('cavalo',hit.id)});
if(typeof ResizeObserver!=='undefined')new ResizeObserver(draw).observe(yardCanvas);
setInterval(()=>{syncYard()},180);

const team=[['Ricardo','Gerente de frota','Renovação, hodômetros e disponibilidade'],['Mariana','Gerente financeira','Caixa, custos e aprovação financeira'],['Carlos','Gerente comercial','Fretes, clientes e negociações'],['Fernanda','Recursos humanos','Motoristas, equipe e benefícios'],['Paulo','Gerente de manutenção','Oficina, revisões e segurança'],['Patrícia','Compras e patrimônio','Cotações, compras e vendas']];
const dealers=[{model:'Scania R500 6x2',kind:'cavalo',price:715000},{model:'Volvo FH 540 6x4',kind:'cavalo',price:790000},{model:'Carreta semirreboque 3 eixos',kind:'carreta',price:275000}];
function fleetBusy(v){return s.trips.some(t=>v.kind==='cavalo'?t.tractor===v.id:t.trailer===v.id)}
function offerRenewals(){if(s.lastOfferDay===s.day)return;s.lastOfferDay=s.day;for(let v of s.fleet){if(status(v)==='NORMAL'||s.deals.some(d=>d.type==='sale'&&d.asset===v.id&&d.kind===v.kind&&d.state==='aberta'))continue;createSaleOffer(v.kind,v.id,true)}}
function createSaleOffer(kind,id,silent=false){let v=s.fleet.find(x=>x.kind===kind&&x.id===id);if(!v)return;if(s.deals.some(d=>d.type==='sale'&&d.asset===id&&d.kind===kind&&d.state==='aberta')){if(!silent)toast('Já existe proposta para esse veículo.');return}let base=kind==='cavalo'?340000:145000,lim=kind==='cavalo'?500000:1000000;let price=Math.max(Math.round(base*.25),Math.round(base*(1-v.km/(lim*1.5))/1000)*1000);s.deals.unshift({id:++s.sequence,type:'sale',kind,asset:id,model:v.model,price,ask:price,round:0,state:'aberta',day:s.day});if(!silent){tab='diretoria2';save();render();toast('Patrícia apresentou uma avaliação simulada.')}}
function createBuyOffer(i){let d=dealers[i];s.deals.unshift({id:++s.sequence,type:'buy',kind:d.kind,model:d.model,price:d.price,ask:d.price,round:0,state:'aberta',day:s.day});tab='diretoria2';save();render();toast('Proposta simulada recebida de fornecedor fictício.');}
function negotiate(id){let d=s.deals.find(x=>x.id===id&&x.state==='aberta');if(!d)return;d.round++;let delta=Math.max(1000,Math.round(d.price*(d.type==='buy'?.018:.014)/1000)*1000);d.price=d.type==='buy'?Math.max(Math.round(d.ask*.90),d.price-delta):Math.min(Math.round(d.ask*1.10),d.price+delta);save();render();toast('Contraproposta aceita na simulação.');}
function approveDeal(id){let d=s.deals.find(x=>x.id===id&&x.state==='aberta');if(!d)return;if(d.type==='buy'){if(s.cash<d.price){toast('Caixa insuficiente. Compra não realizada.');return}let idNum=s.nextAsset;while(s.fleet.some(v=>v.kind===d.kind&&v.id===String(idNum).padStart(4,'0'))||s.retired.some(v=>v.kind===d.kind&&v.id===String(idNum).padStart(4,'0')))idNum++;s.nextAsset=idNum+1;let v={id:String(idNum).padStart(4,'0'),km:0,kind:d.kind,model:d.model};s.fleet.push(v);s.cash-=d.price;s.capex=(s.capex||0)+d.price;addLedger('Investimento','Aquisição patrimonial '+v.id+' — '+d.model,-d.price);d.state='concluída';toast('Compra aprovada: equipamento #'+v.id+' adicionado à frota.')}else{let v=s.fleet.find(v=>v.id===d.asset&&v.kind===d.kind);if(!v){toast('Equipamento não encontrado.');return}if(fleetBusy(v)){toast('Veículo em viagem. Aguarde retornar para concluir a venda.');return}s.fleet=s.fleet.filter(x=>x!==v);s.retired.push({...v,soldDay:s.day,soldFor:d.price});s.cash+=d.price;addLedger('Venda de ativo','Venda patrimonial #'+v.id,d.price);d.state='concluída';toast('Venda aprovada: #'+v.id+' retirado da frota.')}save();render();}
function rejectDeal(id){let d=s.deals.find(x=>x.id===id);if(d)d.state='recusada';save();render()}
function askStaff(i){let p=team[i],alerts=s.fleet.filter(v=>status(v)!=='NORMAL').length;let answers=[`Diretor, temos ${tractors().length} cavalos e ${trailers().length} carretas. ${s.trips.length} conjuntos em viagem e ${alerts} equipamentos em atenção ou limite. As renovações precisam da sua aprovação.`,`Diretor, caixa simulado atual: ${money(s.cash)}. Receitas de fretes: ${money(s.rev)}; custos lançados: ${money(s.expenses)}. O resultado não é lucro líquido contábil.`,`Diretor, temos ${s.trips.length} fretes ativos e ${s.completed} concluídos. O despacho permanece automático.`,`Diretor, o quadro de pessoal é representado por departamentos nesta versão. Folha salarial individual ainda não está implementada.`,`Diretor, veículos no limite são bloqueados para novos fretes. Precisamos validar revisões e ordens de serviço em uma versão futura.`,`Diretor, você pode solicitar cotação, negociar preços e aprovar vendas ou compras na central. Os preços são fictícios, não cotações reais.`];s.chat.push({name:p[0],text:answers[i],day:s.day});s.chat=s.chat.slice(-30);save();render();}
function normalizeQuestion(t){return String(t).toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9# ]/g,' ').replace(/\s+/g,' ').trim()}
function staffAnswer(who,message){
 const q=normalizeQuestion(message), all=s.fleet, cav=tractors(), car=trailers(), has=(...words)=>words.some(w=>q.includes(w));
 const isKm=has('km','quilometr','rodad','hodometro'), isMax=has('maior','mais alto','mais rodado','maxim','top','lider'), isMin=has('menor','menos rodado','minim');
 const category=has('carreta','implemento','semirreboque')?car:has('cavalo','caminhao','caminhoes','trator')?cav:all;
 const label=v=>`${v.kind==='cavalo'?'cavalo mecânico':'carreta'} #${v.id} (${v.model})`;
 const km=v=>num(shownKm(v));
 if(isKm&&(isMax||isMin)){
   const sorted=[...category].sort((a,b)=>shownKm(b)-shownKm(a));const v=isMin?sorted[sorted.length-1]:sorted[0];
   return `Diretor, o veículo com ${isMin?'menor':'maior'} quilometragem ${category===all?'da frota':category===cav?'entre os cavalos':'entre as carretas'} é a ${label(v)}, com ${km(v)} km. Situação: ${status(v)}. ${v.kind==='cavalo'?'Limite de 500.000 km.':'Limite de 1.000.000 km.'} Quilometragem inicial estimada, atualizada pelas viagens do jogo.`;
 }
 const idMatch=q.match(/(?:patrimonio|numero|n |#|veiculo |caminhao |cavalo |carreta )(\d{1,4})\b/);
 if(idMatch && (isKm||has('situacao','status','onde','viagem','vender','avaliar'))){
   const id=idMatch[1].padStart(4,'0');let candidates=category.filter(v=>v.id===id);
   if(candidates.length>1)return `Diretor, o patrimônio #${id} existe como cavalo e como carreta. Especifique qual deseja consultar.`;
   if(!candidates.length)return `Não encontrei o patrimônio #${id} nessa categoria.`;
   const v=candidates[0],t=s.trips.find(t=>v.kind==='cavalo'?t.tractor===id:t.trailer===id);
   return `${label(v)}: ${km(v)} km, situação ${status(v)}; ${t?'em viagem para '+t.to:'na garagem'}. Faltam ${num(Math.max(0,(v.kind==='cavalo'?500000:1000000)-shownKm(v)))} km para o limite.`;
 }
 if(isKm&&has('proximo','perto','atencao','limite','renov')){
   const list=[...category].sort((a,b)=>((a.kind==='cavalo'?500000:1000000)-shownKm(a))-((b.kind==='cavalo'?500000:1000000)-shownKm(b))).slice(0,5);
   return `Os 5 equipamentos mais próximos dos limites são: ${list.map(v=>`${label(v)} — ${km(v)} km (${num(Math.max(0,(v.kind==='cavalo'?500000:1000000)-shownKm(v)))} km restantes)`).join('; ')}. Nenhuma compra ou venda foi autorizada.`;
 }
 if(isKm&&has('media','total','somatorio')){
   const total=category.reduce((n,v)=>n+shownKm(v),0);return `Diretor, ${category.length} equipamentos consultados: ${num(total)} km acumulados e média de ${num(total/category.length)} km por equipamento. Valores simulados.`;
 }
 if(has('quanto','quantos')&&has('viagem','estrada','rodando','viajando'))return `Neste momento, ${s.trips.length} conjuntos estão em viagem e ${Math.max(0,cav.length-s.trips.length)} cavalos estão disponíveis no pátio. Fretes concluídos: ${s.completed}.`;
 if(has('caixa','dinheiro','lucro','receita','despesa','financeir','saldo'))return `Diretor, caixa atual ${money(s.cash)}; receitas de fretes ${money(s.rev)}, despesas operacionais ${money(s.expenses)}, resultado operacional ${money(s.rev-s.expenses)}. Isso ainda não é lucro líquido contábil.`;
 if(has('compr','cotacao','cotac','preco','proposta'))return `Patrícia informa: as cotações simuladas disponíveis são ${dealers.map(d=>`${d.model} por ${money(d.price)}`).join('; ')}. Use Solicitar proposta e aprove a negociação para efetivar a compra.`;
 if(has('vend','renova','substitu'))return `Ricardo informa: ${all.filter(v=>status(v)!=='NORMAL').length} equipamentos estão em atenção ou no limite. Abra a ficha do veículo para solicitar uma avaliação; vendas exigem sua autorização.`;
 if(has('despach','enviar','viajar','frete','operacao automatica')){s.auto=true;autoDispatch();return `Ricardo informa: despacho automático ativo; ${s.trips.length} fretes em andamento. Os veículos aptos são alocados conforme os fretes simulados.`}
 if(has('paus','relogio','tempo','velocidade'))return `O relógio está ${s.paused?'pausado':'ativo'}; velocidade ${s.speed} minutos simulados por segundo. Altere em Gestão.`;
 if(isKm||has('frota','caminh','carreta'))return `Ricardo informa: ${cav.length} cavalos e ${car.length} carretas. ${s.trips.length} conjuntos viajando. Para descobrir o maior hodômetro, pergunte “qual veículo tem a maior quilometragem?”.`;
 if(who==='Fernanda')return 'Diretor, o cadastro individual de funcionários e a folha salarial ainda não foram implementados. Posso informar apenas o que já existe no jogo.';
 if(who==='Paulo')return `Diretor, ${all.filter(v=>status(v)==='LIMITE').length} equipamentos estão no limite de quilometragem. Manutenções detalhadas ainda não foram implementadas.`;
 return `Diretor, não consegui interpretar essa pergunta com segurança. Este chat funciona com consultas e comandos programados, não com IA generativa. Experimente perguntar sobre quilometragem, veículos, viagens, caixa, compras ou vendas.`;
}
function sendStaffMessage(){let input=document.getElementById('staffMessage'),person=document.getElementById('staffPerson');if(!input||!person)return;let msg=input.value.trim();if(!msg)return;let who=person.value;staffSelected=who;staffDraft='';input.value='';s.chat.push({name:'Diretor',text:msg,day:s.day});let answer=staffAnswer(who,msg);s.chat.push({name:who,text:answer,day:s.day});s.chat=s.chat.slice(-60);save();render();let el=document.getElementById('staffMessage');if(el)el.focus()}
function renderBoard(){let alerts=s.fleet.filter(v=>status(v)!=='NORMAL');return `<div class="panel"><h3>👔 Central da Diretoria</h3><p class="note">Você decide compras, vendas e negociações. Os funcionários simulados cuidam da rotina. Todas as propostas são fictícias e só viram transações quando você aprova.</p><div class="row flex"><span>Frota atual</span><b>${tractors().length} cavalos · ${trailers().length} carretas</b></div><div class="row flex"><span>Em alerta / limite</span><b>${alerts.length}</b></div><div class="row flex"><span>Caixa</span><b>${money(s.cash)}</b></div></div><div class="panel"><h3>💬 Conversar com funcionários</h3><p class="muted mini">Chat gratuito por comandos; não é uma IA generativa. As respostas consultam o estado do jogo.</p><select id="staffPerson" class="search" onchange="staffSelected=this.value">${team.map(p=>`<option value="${p[0]}">${p[0]} — ${p[1]}</option>`).join('')}</select><textarea id="staffMessage" class="search" rows="3" oninput="staffDraft=this.value" placeholder="Escreva sua ordem ou pergunta ao funcionário..."></textarea><button class="btn" onclick="sendStaffMessage()">Enviar mensagem</button><div class="list">${s.chat.slice(-12).map(m=>`<div class="row"><b>${esc(m.name)}</b><p>${esc(m.text)}</p></div>`).join('')}</div></div><div class="panel"><h3>💬 Consultas rápidas</h3>${team.map((p,i)=>`<div class="row flex"><div><b>${p[0]} — ${p[1]}</b><div class="muted mini">${p[2]}</div></div><button class="btn secondary" onclick="askStaff(${i})">Conversar</button></div>`).join('')}<div class="list">${s.chat.slice(-6).reverse().map(m=>`<div class="row"><b>${m.name}</b><p>${esc(m.text)}</p></div>`).join('')}</div></div><div class="panel"><h3>🚛 Solicitar compra de equipamentos</h3><p class="muted mini">Valores de referência simulados; o jogo não contata concessionárias.</p>${dealers.map((d,i)=>`<div class="row flex"><div><b>${d.model}</b><div class="muted">${money(d.price)}</div></div><button class="btn" onclick="createBuyOffer(${i})">Solicitar proposta</button></div>`).join('')}</div><div class="panel"><h3>🤝 Propostas para negociar</h3>${s.deals.filter(d=>d.state==='aberta').length?s.deals.filter(d=>d.state==='aberta').map(d=>`<div class="row"><b>${d.type==='buy'?'COMPRA':'VENDA'} — ${esc(d.model)} ${d.asset?'#'+d.asset:''}</b><p>Oferta ${money(d.price)} · Rodadas ${d.round}</p><div class="actions"><button class="btn secondary" onclick="negotiate(${d.id})">Negociar</button><button class="btn" onclick="approveDeal(${d.id})">Aprovar ${d.type==='buy'?'compra':'venda'}</button><button class="btn secondary" onclick="rejectDeal(${d.id})">Recusar</button></div></div>`).join(''):'<p class="muted">Sem propostas pendentes.</p>'}</div></div><div class="panel"><h3>📋 Veículos para avaliar venda</h3><p class="muted mini">Veículos em viagem não podem ser vendidos antes de retornarem. A negociação pode ser iniciada antes.</p><div class="list">${s.fleet.filter(v=>status(v)!=='NORMAL').slice(0,30).map(v=>`<div class="row flex"><span>#${v.id} · ${v.kind} · ${num(shownKm(v))} km</span><button class="btn secondary" onclick="createSaleOffer('${v.kind}','${v.id}')">Avaliar venda</button></div>`).join('')||'<p class="muted">Nenhum veículo atingiu a faixa de atenção. Você também pode solicitar avaliação ao abrir a ficha de qualquer veículo na Frota.</p>'}</div></div><div class="panel"><h3>📑 Histórico de negociações</h3>${s.deals.filter(d=>d.state!=='aberta').slice(0,12).map(d=>`<div class="row flex"><span>${d.type==='buy'?'Compra':'Venda'} ${esc(d.model)} ${d.asset||''}</span><b>${money(d.price)} · ${d.state}</b></div>`).join('')||'<p class="muted">Nenhuma negociação concluída.</p>'}</div>`}

document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>setTab(b.dataset.tab));let previous=s.lastTick;s.lastTick=Date.now();let backlog=Math.min(7*86400000,Math.max(0,Date.now()-previous));if(!s.paused&&backlog>0){let m=Math.floor(backlog/1000*s.speed);s.minute+=m;let d=Math.floor(s.minute/1440);s.minute%=1440;if(d)advance(Math.min(d,7),true)}if(s.trips.length===0)autoDispatch();offerRenewals();save();render();setInterval(tick,1000);
